var n=`0966-taiyaki`;var a=`world-0966`;var o=`JP`;var t=`east-asia`;var s=8;var l=38;var r={en:`Taiyaki`,ua:`Тайякі`};var d={en:`Taiyaki is a Japan dish made with all-purpose flour, chicken egg, whole cow milk, baking powder. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Тайякі, страва кухні країни Японія. Основні складники: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко, розпушувач тіста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,260,`g`],[`chicken-egg`,2,`pcs`],[`white-granulated-sugar`,75,`g`],[`whole-cow-milk`,300,`ml`],[`baking-powder`,7,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`red-bean-paste-anko`,280,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 20 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 20 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:20,i:[[`canola-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`honey`,35,`g`]]}];var m={slug:n,id:a,country:`JP`,region:t,servings:8,minutes:38,title:r,text:d,steps:g};export{o as country,m as default,a as id,l as minutes,t as region,s as servings,n as slug,g as steps,d as text,r as title};